{
  "id": "filter_methylation_extremes",
  "name": "Filter Methylation Extremes",
  "version": "1.0.0",
  "container": "quay.io/biocontainers/python:3.12.12",
  "inputs": [
    {
      "name": "input_tabular",
      "type": "data",
      "format": "tabular",
      "label": "Input tabular dataset"
    }
  ],
  "outputs": [
    {
      "name": "filtered_output",
      "format": "tabular",
      "label": "Filtered output",
      "from_work_dir": "filtered.tabular"
    }
  ],
  "shell_command": "python3 -c \"\nimport sys\nheader = sys.stdin.readline()\nsys.stdout.write(header)\nfor line in sys.stdin:\n    if not line.strip():\n        continue\n    cols = line.split(chr(9))\n    try:\n        val = float(cols[7])\n        if val > 90.0 or val < 10.0:\n            sys.stdout.write(line)\n    except (ValueError, IndexError):\n        pass\n\" < \"$input_tabular\" > \"$filtered_output\""
}
